private Path locatePomDirectory(Path root) throws IOException {
    if (Files.isRegularFile(root.resolve("pom.xml"))) return root;
    try (DirectoryStream<Path> dirs = Files.newDirectoryStream(root)) {
        List<Path> candidates = new ArrayList<>();
        for (Path child : dirs) {
            if (Files.isDirectory(child) && Files.isRegularFile(child.resolve("pom.xml"))) candidates.add(child);
        }
        Collections.sort(candidates);
        if (!candidates.isEmpty()) return candidates.get(0);
    }
    return null;
}
