private String limitLog(String log) {
    if (log == null) return null;
    if (log.length() <= MAX_LOG_LENGTH) return log;
    int head = MAX_LOG_LENGTH / 2;
    int tail = MAX_LOG_LENGTH - head;
    return log.substring(0, head) + System.lineSeparator() + "...[log truncated]..." + System.lineSeparator() + log.substring(log.length() - tail);
}
